INSERT INTO public.categories (id, name, slug, description, sort_order) VALUES
('c0000000-0000-0000-0000-000000000001', 'Bedsheets', 'bedsheets', 'Fitted & Flat French Linen and high-thread cotton sateen designed for immediate softness.', 1),
('c0000000-0000-0000-0000-000000000002', 'Pillows & Covers', 'pillows', 'Cloud-loft Down Pillows and pure linen envelope shams that elevate cervical relaxation.', 2),
('c0000000-0000-0000-0000-000000000003', 'Duvets & Inserts', 'duvets', 'All-season breathable French flax covers paired with hypoallergenic goose-down inserts.', 3)
INSERT INTO public.products (id, category_id, name, slug, tagline, description, base_price, rating, review_count, material, thread_count_or_gsm, origin, is_bestseller) VALUES
('p0000000-0000-0000-0000-000000000001', 'c0000000-0000-0000-0000-000000000001', 'The French Flax Linen Sheet Set', 'french-flax-linen-sheet-set', 'Stone-Washed Normandy Flax • Impossibly Soft from Night One', 'Crafted from 100% long-staple French flax harvested in Normandy. Pre-washed with volcanic stones for signature lived-in drape, breathability, and exceptional temperature regulation.', 285.00, 4.90, 438, '100% French Flax Linen', '175 GSM', 'Normandy, France', true),
('p0000000-0000-0000-0000-000000000002', 'c0000000-0000-0000-0000-000000000001', 'The Washed Linen Sheet Set', 'washed-linen-sheet-set', 'Volcanic Stone-Washed • Tactile Warmth & Organic Drape', 'Generously washed with volcanic pumice stones for that coveted relaxed architectural drape.', 285.00, 4.90, 428, '100% French Flax Linen', '180 GSM', 'Normandy, France', true),
('p0000000-0000-0000-0000-000000000003', 'c0000000-0000-0000-0000-000000000001', 'Organic Percale Crisp Sheet Set', 'organic-percale-crisp-sheet-set', 'Cool, Breathable & Matte • Classic Boutique Hotel Weave', 'Woven from 100% long-staple certified organic cotton. Features a traditional 1-over-1 percale weave.', 220.00, 4.80, 312, '100% GOTS Organic Cotton', '300 Thread Count', 'Aegean Coast, Turkey', false),
('p0000000-0000-0000-0000-000000000004', 'c0000000-0000-0000-0000-000000000001', 'Lustrous Sateen Luxe Bedding Set', 'lustrous-sateen-luxe-bedding-set', '480 Thread Count • Silky Luster & Velvet-Soft Touch', 'Crafted with ultra-long staple Egyptian cotton spun into fine yarns with subtle champagne luster.', 260.00, 4.90, 284, '100% Giza Egyptian Cotton', '480 Thread Count', 'Nile Delta, Egypt', false),
('p0000000-0000-0000-0000-000000000005', 'c0000000-0000-0000-0000-000000000001', 'Heirloom Belgian Flax Fitted Sheet', 'heirloom-belgian-flax-fitted-sheet', 'Single-Farm Belgian Linen • 360° Grip Pocket', 'Tailored from single-farm Belgian flax with 16-inch deep pockets and full-perimeter elastic.', 160.00, 4.70, 165, '100% Belgian Flax', '185 GSM', 'Flanders, Belgium', false),
('p0000000-0000-0000-0000-000000000006', 'c0000000-0000-0000-0000-000000000003', 'Cloud Goose Down Duvet Insert', 'cloud-goose-down-duvet-insert', '750 Fill Power • Ethical RDS European Goose Down', 'Filled with 750 fill-power European white goose down encased in a silent 400-thread count German batiste shell.', 340.00, 5.00, 215, '750 FP White Goose Down & Cotton Batiste', '750 Fill Power', 'Bavaria, Germany', true),
('p0000000-0000-0000-0000-000000000007', 'c0000000-0000-0000-0000-000000000003', 'Heirloom Linen Duvet Cover', 'heirloom-linen-duvet-cover', 'Pure Stone Wash • Genuine Horn Buttons & Corner Ties', 'Spun from Normandy flax, this cover showcases raw organic slub and subtle wrinkles with horn button closures.', 220.00, 4.80, 189, '100% French Flax Linen', '180 GSM', 'Normandy, France', true),
('p0000000-0000-0000-0000-000000000008', 'c0000000-0000-0000-0000-000000000003', 'Lightweight Summer Down-Alternative Duvet', 'lightweight-summer-down-alternative-duvet', 'Micro-Cluster Cloudfiber • Tailored for Warm Sleepers', 'Engineered specifically for summer warmth with hypoallergenic micro-cluster recycled fibers.', 210.00, 4.70, 142, 'Hypoallergenic Cloudfiber & Organic Cotton', '300 GSM', 'Porto, Portugal', false),
('p0000000-0000-0000-0000-000000000009', 'c0000000-0000-0000-0000-000000000002', 'Pure Silk & French Linen Pillow Pair', 'pure-silk-french-linen-pillow-pair', 'Set of 2 • 22-Momme Mulberry Silk Front & Linen Reverse', 'The front features 22-momme Mulberry silk; the reverse offers breathable stone-washed French linen.', 110.00, 4.90, 310, 'Mulberry Silk & French Linen', '22 Momme Silk', 'Lyon, France', true),
('p0000000-0000-0000-0000-000000000010', 'c0000000-0000-0000-0000-000000000002', 'Linen Pillow Shams (Set of 2)', 'linen-pillow-shams-set-of-2', 'Enzyme-Washed Normandy Flax • Deep Envelope Pocket', 'Woven from certified European flax with tailored 8-inch envelope enclosure.', 75.00, 4.80, 224, '100% French Flax Linen', '175 GSM', 'Normandy, France', false),
('p0000000-0000-0000-0000-000000000011', 'c0000000-0000-0000-0000-000000000002', 'Cloud-Loft Goose Down Pillow', 'cloud-loft-goose-down-pillow', 'Dual-Chamber Support • Hypoallergenic Bavarian Down', 'Dense feather core for cervical alignment surrounded by outer fluffy 750 fill-power goose down.', 145.00, 4.90, 198, '750 FP White Goose Down & Cotton Cambric', '750 Fill Power', 'Bavaria, Germany', false),
('p0000000-0000-0000-0000-000000000012', 'c0000000-0000-0000-0000-000000000002', 'Ergonomic Memory Latex Contour Pillow', 'ergonomic-memory-latex-contour-pillow', 'Natural Talalay Latex Core • Orthopedic Align & Cool', 'Open-cell natural Talalay latex molded to support side and back sleeping alignment.', 120.00, 4.80, 96, '100% Talalay Latex & Organic Cotton Cover', 'Orthopedic', 'Netherlands', false)
